questionvariables.text:
/*Method of washers*/
y1:sin(x/2);
y2:cos(x/2);
interval_1:0;
aa:rand([2,4,6]);
interval_2:pi/aa;
/*solution variables*/
sol1:pi*((y2)^2-(y1)^2);
sol2:int(sol1,x,0,interval_2);
ta:sol2;
sol3:if interval_2=pi/2 then 1 elseif interval_2=pi/4 then sqrt(2)/2 elseif interval_2=pi/6 then 1/2 ;
